sys_script_include.script:
gs.include("IllumioConstants");
var IllumioUtilsAJAX = Class.create();
IllumioUtilsAJAX.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // On the prototype, not in initialize -- see the note in IllumioUpdatePCE.
    logger: new IllumioLogger(null, 'IllumioUtilsAJAX'),

    FIELD_NAME_TYPE: "field_name",

	/**
     * get field name type fields.
     * @return {String} fields with type field name.
     */
    getFieldNameTypeFields: function() {
        var eligibleFields = [];
        var mappingsGR = new GlideRecordSecure(TABLE_PCE_FIELD_MAPPING);
        mappingsGR.initialize();
        for (var field in mappingsGR) {
            // indexOf, not String.prototype.startsWith: the rest of the server code is strict
            // ES5 and this was the last ES6 construct left in it. It ran, so the scope is on an
            // engine that supports it -- this is a consistency fix, not a crash fix. It stops
            // being cosmetic the moment anything here is back-ported to a Rhino scope, which is
            // exactly what the MID script includes are.
            if (field.indexOf("sys_") === 0 || field == "order_by_column_name")
                continue;
            try {
                if (mappingsGR.getElement(field).getED().getInternalType() == this.FIELD_NAME_TYPE)
                    eligibleFields.push(field);
            } catch (e) {
                this.logger.error("Exception while fetching fields: " + e);
            }

        }
        return JSON.stringify(eligibleFields);
    },

    /**
     * Render a Sync Filter's Label Condition as a readable expression.
     *
     * For DISPLAY ONLY. Nothing is stored -- the caller passes the condition currently on the
     * form, not a saved record, so the expression tracks what the author is building rather than
     * what was last saved.
     *
     * The rendering runs on the server because it needs the parser the evaluator itself uses
     * (so the description cannot drift from the query) and because resolving a dimension sys_id
     * to its key is a database read.
     *
     * @returns {String} JSON { text: String, errors: Array } -- text is "" when the condition
     *                   does not parse
     */
    describeLabelCondition: function() {
        try {
            var syncUtils = new IllumioSyncUtils();
            var described = syncUtils.describeLabelCondition(
                this.getParameter("sysparm_label_condition"));

            return JSON.stringify({
                text: described.text,
                errors: described.errors
            });
        } catch (ex) {
            this.logger.error("[describeLabelCondition] Exception while describing a label condition. " +
                "Exception: " + ex);
            return JSON.stringify({
                text: "",
                errors: []
            });
        }
    },

    /**
     * Is an Illumio job running right now?
     *
     * The client half of the one-job-at-a-time guard, and only the client half. It exists so a
     * button that cannot proceed says so immediately instead of submitting the form and coming
     * back with an error message. The authoritative check runs server-side immediately before
     * the job record is inserted -- two people clicking within the same second both pass this
     * one.
     *
     * Reads sysparm_config_sys_id and scopes the check to that PCE Configuration. When the
     * parameter is absent the check stays instance-wide, which blocks more than necessary rather
     * than less -- the recoverable direction for a guard, and what every caller did before.
     *
     * The parameter is not validated against anything. It is only ever fed to an addQuery on a
     * value the client already has on the form it is sitting on, and a junk sys_id matches no
     * rows, so the worst outcome is the guard reporting idle. The server-side check is
     * authoritative regardless.
     *
     * @returns {String} JSON { running: Boolean, message: String }
     */
    hasRunningJob: function() {
        try {
            var utils = new IllumioUtils();
            var runningJob = utils.getRunningJob(this.getParameter("sysparm_config_sys_id"));

            return JSON.stringify({
                running: !!runningJob,
                message: utils.describeRunningJob(runningJob)
            });
        } catch (ex) {
            this.logger.error("[hasRunningJob] Exception while checking for a running job. " +
                "Exception: " + ex);
            // Fail open. The server-side check is what actually enforces this, and blocking the
            // button on an error here would make a transient fault look like a permanent one.
            return JSON.stringify({
                running: false,
                message: ""
            });
        }
    },

    type: 'IllumioUtilsAJAX'
});
